class Refusal(Exception):pass

def need(value,code):
    if not value:raise Refusal(code)

def sha(value):return hashlib.sha256(value).hexdigest()

def json_path(value):
    if isinstance(value,Path):return str(value)
    raise TypeError('Unsupported private JSON value')

def canonical(value):return json.dumps(value,ensure_ascii=False,sort_keys=True,separators=(',',':'),default=json_path).encode()

def read(path):return json.loads(Path(path).read_bytes())

def filehash(path):
    h=hashlib.sha256()
    with Path(path).open('rb') as f:
        for block in iter(lambda:f.read(65536),b''):h.update(block)
    return h.hexdigest()

def write(path,value,raw=False):
    path=Path(path);need(path.is_relative_to(N) or path.is_relative_to(B),'OUTPUT_NAMESPACE')
    with path.open('xb') as f:
        f.write(value if raw else canonical(value)+b'\n');f.flush();os.fsync(f.fileno())
    path.chmod(0o600)

def event(phase,**values):
    record={'phase':phase,'at':time.time(),**values}
    folder=N if N.is_dir() else B
    if folder.is_dir():
        with (folder/'events.redacted.jsonl').open('ab') as f:
            f.write(canonical(record)+b'\n');f.flush();os.fsync(f.fileno())
    print('PR477_'+phase,flush=True)

def remember_build_secrets(values):
    for key,value in (values or {}).items():
        if isinstance(value,str) and value and (len(value)>=8 or re.search(r'key|token|secret|passw|credential|authorization|auth_users|vapid',key,re.I)):
            BUILD_SECRET_VALUES.add(value)

def redact_build_output(raw):
    value=raw.decode('utf-8','replace') if isinstance(raw,bytes) else str(raw or '')
    for secret in sorted(BUILD_SECRET_VALUES,key=len,reverse=True):value=value.replace(secret,'[REDACTED]')
    value=re.sub(r'(?i)\bBearer\s+[A-Za-z0-9._~+/=-]+','Bearer [REDACTED]',value)
    value=re.sub(r'(?i)((?:token|password|secret|api[_-]?key|authorization|vapid[_-]?(?:private[_-]?)?key)\s*[:=]\s*)[^\s,;]+',r'\1[REDACTED]',value)
    value=re.sub(r'([a-zA-Z][a-zA-Z0-9+.-]*://)[^\s/:@]+:[^\s/@]+@',r'\1[REDACTED]@',value)
    return value.encode()

def failed_build_logs(log,stdout,stderr):
    result={'build_output_redacted':True}
    for label,raw in [('stdout',stdout),('stderr',stderr)]:
        content=redact_build_output(raw);target=log.with_name(log.name.removesuffix('.rc.json')+'.'+label+'.redacted.log')
        write(target,content,True);result[label+'_redacted_sha256']=sha(content)
    return result

def run(argv,purpose,timeout=180,data=None,env=None,accepted=(0,)):
    global RUN_NUMBER
    RUN_NUMBER+=1
    log=(N if N.is_dir() else B)/('%04d-%s.rc.json'%(RUN_NUMBER,purpose))
    code=re.sub(r'[^A-Z0-9_]','_',purpose.upper())
    try:r=sp.run(argv,input=data,capture_output=True,timeout=timeout,env=GLOBAL_ENV if env is None else env,cwd=str(REPO))
    except sp.TimeoutExpired as error:
        record={'timeout':True,'outcome':'INSPECT_ONLY'}
        if argv[:2]==['docker','build']:record.update(failed_build_logs(log,error.stdout,error.stderr))
        write(log,record);raise Refusal('TIMEOUT_'+code) from None
    record={'returncode':r.returncode}
    if r.returncode not in accepted and argv[:2]==['docker','build']:record.update(failed_build_logs(log,r.stdout,r.stderr))
    write(log,record)
    need(r.returncode in accepted,'COMMAND_'+code)
    return r

