def source_index(row):
    changed=run(['docker','diff',row['Id']],'app-diff').stdout.decode().splitlines()
    app=[line.split(' ',1)[1] for line in changed if ' ' in line and (line.split(' ',1)[1]=='/app' or line.split(' ',1)[1].startswith('/app/'))]
    if app:
        check='const f=require("node:fs");for(const p of JSON.parse(process.argv[1])){const s=f.lstatSync(p);if(!s.isDirectory()||s.isSymbolicLink())throw Error("UNBAKED_APP_FILE");}console.log("APP_DIRECTORIES_ONLY");'
        run(['docker','exec',row['Id'],'node','-e',check,json.dumps(app)],'app-diff-types')
    actual=json.loads(run(['docker','exec',row['Id'],'node','-e',RUNTIME_INDEX_JS],'live-source-index').stdout)
    parent=image(row['Image']);need(not parent['Config'].get('Healthcheck') or parent['Config']['Healthcheck'].get('Test')==['NONE'],'UNPLANNED_IMAGE_HEALTHCHECK')
    observed,_=docker(row['Image'],['-e',RUNTIME_INDEX_JS],'source-index')
    need(actual and {r['path']:r for r in actual}=={r['path']:r for r in json.loads(observed.stdout)},'UNBAKED_SOURCE_FILES')
    return actual

