def prepare_recipe(plan,images):
    common=plan['common'];before=json.loads(run(common+['config','--format','json'],'base-config').stdout)
    for service in SERVICE_NAMES:need(image(before['services'][service]['image'])['Id']==inspect('synapse-'+service+'-1')['Image'],'CURRENT_EFFECTIVE_IMAGE_DRIFT')
    overlay=N/'candidate.json';write(overlay,{'services':{s:{'image':v} for s,v in images.items()}})
    command=common+['-f',str(overlay)];rendered=json.loads(run(command+['config','--format','json'],'candidate-config').stdout);expected=copy.deepcopy(before)
    for service,img in images.items():expected['services'][service]['image']=img
    need(rendered==expected,'ONLY_CRM_MCP_IMAGES_MAY_CHANGE')
    for service in TARGETS:
        health=rendered['services'][service].get('healthcheck');need(not health or health.get('disable') is True,'UNPLANNED_COMPOSE_HEALTHCHECK')
        name='sb477-r1-sleep-'+service;need(inspect(name,True) is None,'SLEEP_PROBE_EXISTS');OWNED[name]=images[service]
        try:
            run(command+['run','--detach','--no-deps','--pull','never','--name',name,'--label',LABEL+'='+SOURCE_SHA,'--entrypoint','sleep',service,'120'],'sleep-probe')
            probe=inspect(name);old=plan['before'][service]
            need(probe['Image']==images[service] and env_map(probe)==env_map(old) and mounts(probe)==mounts(old) and network(probe)==network(old),'SLEEP_ENV_NETWORK_MOUNTS')
            need(probe['Config']['User']==old['Config']['User'] and probe['Config']['WorkingDir']==old['Config']['WorkingDir'] and probe['Config']['Entrypoint']==['sleep'] and probe['Config']['Cmd']==['120'],'SLEEP_PROCESS_CONTRACT')
        finally:remove_owned(name)
    rollback=N/'rollback.json';write(rollback,{'services':{s:{'image':r['Image']} for s,r in plan['before'].items()}})
    plan.update(command=command,images=images,rollback_command=command+['-f',str(rollback)])
    plan['input_pins'].update({str(overlay):filehash(overlay),str(rollback):filehash(rollback)});stable(plan)

def trial(plan,folder):
    f=folder/'crm';before=f/'before.sqlite'
    if not before.exists():backup(plan['databases']['crm'],before)
    current=f/'crm.sqlite';need(not current.exists(),'TRIAL_TARGET_EXISTS');shutil.copyfile(before,current);current.chmod(0o600)
    old=fingerprint(before,plan['images']['crm'],'trial-before')
    result,_=docker(plan['images']['crm'],['/verify.cjs'],'trial-constructor',mounts=[f'type=bind,src={f},dst=/trial',f'type=bind,src={before},dst=/trial/before.sqlite,readonly',f'type=bind,src={B/"verifier477.cjs"},dst=/verify.cjs,readonly',f'type=bind,src={N/"package477"},dst=/package477,readonly'])
    need(b'PASS agent477 three_empty_tables exact_schema no_agent_tools_called' in result.stdout,'TRIAL_RECEIPT')
    after=fingerprint(current,plan['images']['crm'],'trial-after');proof={'crm':{'before':old,'after':after,'before_file':str(before)}}
    write(folder/'proofs.private.json',proof);event('TRIAL_PASS',cohort=folder.name);return proof

def no_writers(plan):
    files=[Path(str(p)+suffix) for p in plan['databases'].values() for suffix in ['', '-wal','-shm']]
    for row in running():
        for mount in row.get('Mounts',[]):
            source=Path(mount['Source']);need(not mount.get('RW') or not any(p==source or source in p.parents for p in files),'CRM_DATABASE_WRITER_RUNNING')

def stop_crm(plan,allow_missing=False):
    row=inspect(TARGETS['crm'],allow_missing)
    if row:
        need(row['Image'] in [plan['before']['crm']['Image'],plan['images']['crm']],'UNEXPECTED_CRM_IMAGE')
        old=plan['before']['crm'];need(normalized_config(row)==normalized_config(old) and mounts(row)==mounts(old) and normalized_host_config(row)==normalized_host_config(old),'UNEXPECTED_CRM_SETTINGS')
        if row['State']['Running']:run(['docker','stop','--time','120',row['Id']],'stop-crm',timeout=150)
    no_writers(plan)

def readiness(service):
    path='/summary?from=2026-11-03&to=2026-11-03' if service=='crm' else '/health';port='8080' if service=='crm' else None
    code=('const c=require("/app/server.js").loadConfig();const url="http://127.0.0.1:"+c.port+"/health";' if service=='tasks-mcp' else 'const url='+json.dumps('http://127.0.0.1:8080'+path)+';')
    code+='fetch(url,{signal:AbortSignal.timeout(10000)'+(',headers:{"x-api-key":process.env.API_KEY}' if service=='crm' else '')+'}).then(async r=>{if(r.status!==200)throw Error("HTTP");const d=await r.json();if(!d||typeof d!=="object")throw Error("BODY");console.log("READY");}).catch(()=>{process.exitCode=1;});'
    for _ in range(20):
        r=run(['docker','exec',TARGETS[service],'node','-e',code],'ready-'+service,timeout=20,accepted=(0,1))
        if r.returncode==0 and b'READY' in r.stdout:return
        time.sleep(1)
    raise Refusal('READINESS_FAILED')

